<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Deliveries | EcoCycle</title><link rel="stylesheet" href="assets/css/style_delivery.css"></head><body><?php require APP_PATH . '/views/layouts/header_sidebar_delivery.php'; ?><main class="main assigned-page"><section class="delivery-dashboard-heading"><p class="eyebrow">Your workload</p><h1>Assigned Deliveries</h1><p>Jobs you accepted from the open delivery list.</p></section><section class="assigned-request-list"><?php if($jobs): foreach($jobs as $job): ?><article class="assigned-request-card"><div class="assigned-request-main"><p class="eyebrow">Delivery #<?php echo (int)$job['delivery_id']; ?></p><h2><?php echo htmlspecialchars($job['item_name']??'Item'); ?></h2><div class="assigned-request-meta"><span>Pickup: <?php echo htmlspecialchars($job['pickup_location']??'N/A'); ?></span><span>Receiver: <?php echo htmlspecialchars($job['receiver_name']??'N/A'); ?></span></div></div><div class="assigned-request-actions"><span class="request-status"><?php echo htmlspecialchars($job['status']); ?></span><?php if($job['proposed_charge']===null&&$job['status']==='Charge Pending'): ?><form class="inline-action-form" method="post" action="index.php?url=delivery/charge"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrfToken); ?>"><input type="hidden" name="delivery_id" value="<?php echo (int)$job['delivery_id']; ?>"><input type="number" name="charge" min="1" step="0.01" placeholder="Charge (BDT)" required><button class="request-accept" type="submit">Send Charge</button></form><?php elseif(in_array($job['status'],['Charge Accepted','Arrived at Pickup','Picked Up'],true)): ?><form class="inline-action-form" method="post" action="index.php?url=delivery/progress"><input type="hidden" name="csrf_token" value="<?php echo htmlspecialchars($csrfToken); ?>"><input type="hidden" name="delivery_id" value="<?php echo (int)$job['delivery_id']; ?>"><?php if($job['status']==='Charge Accepted'): ?><button class="request-accept" name="action" value="arrived">Mark Arrived</button><?php elseif($job['status']==='Arrived at Pickup'): ?><button class="request-accept" name="action" value="picked_up">Mark Picked Up</button><?php else: ?><button class="request-accept" name="action" value="complete">Mark Completed</button><?php endif; ?></form><?php endif; ?></div></article><?php endforeach; else: ?><div class="assigned-empty">No delivery has been assigned to you yet.</div><?php endif; ?></section></main></body></html>
